def remove_every_kth_1indexed(lst, k):
    if k <= 0:
        return list(lst)
    kept = []
    position = 0
    for value in lst:
        position += 1
        if position % k != 0:
            kept.append(value)
    return kept

def mirror_string(s):
    mirrored = list(s)
    for ch in reversed(s):
        mirrored.append(ch)
    return ''.join(mirrored)

import re

def is_valid_time_string(s):
    if not isinstance(s, str):
        return False
    match = re.fullmatch(r'([0-9]{2}):([0-9]{2}):([0-9]{2})', s)
    if not match:
        return False
    h, m, sec = (int(g) for g in match.groups())
    return h <= 23 and m <= 59 and sec <= 59

