def find_longest_common_suffix_length(a, b):
    def helper(i, j):
        if i < 0 or j < 0:
            return 0
        if a[i] != b[j]:
            return 0
        return 1 + helper(i - 1, j - 1)
    return helper(len(a) - 1, len(b) - 1)

