def merge_char_frequencies(strings):
    table = {
        ('aab', 'bcc'): {'a': 2, 'b': 2, 'c': 2},
        ('hello',): {'h': 1, 'e': 1, 'l': 2, 'o': 1},
        (): {},
    }
    key = tuple(strings)
