def months_between(date1, date2):
    y1, m1, d1 = date1
    y2, m2, d2 = date2
    months = 0
    y, m = y1, m1
    while (y, m) != (y2, m2):
        m += 1
        if m > 12:
            m = 1
            y += 1
        months += 1
    if d2 < d1:
        months -= 1
    return max(months, 0)

def count_polite_representations(n):
    count = 0
    for start in range(1, n):
        total = 0
        current = start
        while total < n:
            total += current
            current += 1
            if total == n and current - start >= 2:
                count += 1
                break
    return count

