import statistics

def median_absolute_deviation(nums):
    med = statistics.median(nums)
    deviations = [abs(x - med) for x in nums]
    return float(statistics.median(deviations))

def days_since_start_of_quarter(year, month, day):
    def day_of_year(y, m, d):
        base_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        leap = (y % 4 == 0 and y % 100 != 0) or y % 400 == 0
        total = d
        for i in range(m - 1):
            length = base_lengths[i]
            if i == 1 and leap:
                length = 29
            total += length
        return total

    quarter_index = (month - 1) // 3
    quarter_start_month = quarter_index * 3 + 1
    return day_of_year(year, month, day) - day_of_year(year, quarter_start_month, 1)

