def sort_points_by_manhattan_distance(points):
    decorated = []
    for x, y in points:
        decorated.append((abs(x) + abs(y), x, y))
    decorated.sort()
    return [(x, y) for _, x, y in decorated]

def primes_up_to(n):
    def is_prime(num):
        if num < 2:
            return False
        return all(num % d != 0 for d in range(2, int(num ** 0.5) + 1))
    return [num for num in range(2, n + 1) if is_prime(num)]

