import re

def count_case_transitions(s):
    pattern = re.compile(r'(?=([A-Za-z][A-Za-z]))')
    total = 0
    for match in pattern.finditer(s):
        a, b = match.group(1)
        if a.isupper() != b.isupper():
            total += 1
    return total

