def is_valid_hsl_tuple(t):
    if not isinstance(t, tuple) or len(t) != 3:
        return False
    hue, saturation, lightness = t

    def in_range(value, lo, hi):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and lo <= value <= hi

    if not isinstance(hue, int) or isinstance(hue, bool):
        return False
    return 0 <= hue <= 360 and in_range(saturation, 0, 100) and in_range(lightness, 0, 100)

